#include <bits/stdc++.h>using namespace std;// print a number as the sum of round numbers// 1234 -> 1000 200 30 4int main() {    int t;    cin >> t;    while(t-- >0) {        int x;        cin >> x;        int place = 1;        int y = x;        int count = 0;        while(y>0){            int rem = y%10;            if(rem!=0) {                count++;            }            y/=10;        }        cout << count << endl;        while(x>0) {            int rem = x%10;            if(rem!=0) {                cout << rem*place << " ";            }            place*=10;            x/=10;        }        cout << "\n";    }}